// Confirms the interview time the Book Meeting agent proposed, or picks the
// first free slot itself when the proposal breaks a rule: a 30-minute call on a
// weekday after today, 8:00 AM to 5:00 PM Central time, within the week of
// calendar read before this node, and clear of every timed busy event.
const TIME_ZONE = 'America/Chicago';
const OPEN_MINUTES = 8 * 60;
const CLOSE_MINUTES = 17 * 60;
const SLOT_MS = 30 * 60 * 1000;
const WINDOW_MS = 8 * 24 * 60 * 60 * 1000;

const partFormatter = new Intl.DateTimeFormat('en-US', {
  timeZone: TIME_ZONE, weekday: 'short', year: 'numeric', month: '2-digit', day: '2-digit',
  hour: '2-digit', minute: '2-digit', hourCycle: 'h23',
});

function local(date) {
  const p = Object.fromEntries(partFormatter.formatToParts(date)
    .filter(({ type }) => type !== 'literal')
    .map(({ type, value }) => [type, value]));
  return { day: `${p.year}-${p.month}-${p.day}`, weekday: p.weekday, minutes: Number(p.hour) * 60 + Number(p.minute) };
}

const events = $input.all().map(({ json }) => json);
const failed = events.find((event) => event && event.error);
if (failed) throw new Error('The interviewer calendar could not be read: ' + JSON.stringify(failed.error));

// Cancelled, "show as free" and all-day events never block a slot.
const busy = events.map((event) => {
  if (!event || event.status === 'cancelled' || event.transparency === 'transparent') return null;
  const start = new Date(event.start?.dateTime ?? NaN);
  const end = new Date(event.end?.dateTime ?? NaN);
  return end > start ? { start, end } : null;
}).filter(Boolean);

const now = new Date();
const today = local(now).day;

function isFree(start) {
  const end = new Date(start.getTime() + SLOT_MS);
  const from = local(start);
  const to = local(end);
  return from.day > today && from.weekday !== 'Sat' && from.weekday !== 'Sun' &&
    from.day === to.day && from.minutes >= OPEN_MINUTES && to.minutes <= CLOSE_MINUTES &&
    end.getTime() <= now.getTime() + WINDOW_MS &&
    !busy.some((slot) => start < slot.end && end > slot.start);
}

const proposal = $('Book Meeting').first().json.output ?? {};
const proposed = new Date(proposal.startTime);
let start = !Number.isNaN(proposed.getTime()) && proposed.getTime() % SLOT_MS === 0 && isFree(proposed) ? proposed : null;
const source = start ? 'agent' : 'fallback';

for (let ms = Math.ceil(now.getTime() / SLOT_MS) * SLOT_MS; !start && ms < now.getTime() + WINDOW_MS; ms += SLOT_MS) {
  if (isFree(new Date(ms))) start = new Date(ms);
}
if (!start) throw new Error('No free 30-minute interview slot in the next week.');

return [{
  json: {
    startTime: start.toISOString(),
    endTime: new Date(start.getTime() + SLOT_MS).toISOString(),
    source,
    proposedStartTime: String(proposal.startTime ?? ''),
  },
  pairedItem: { item: 0 },
}];
